{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "FECUMI-101, which shares the piperazine-aryl and butyl-dione scaffold with the query, crossed the BBB in baboon PET studies, directly supporting meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "A [11C] analogue with the same piperazine-aryl/butyl-dione core penetrated the BBB in baboon PET with regional uptake matching 5-HT1A receptor distribution, supporting CNS penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "A close pyridinone-piperazine analogue showed a brain:plasma ratio of 3.7 in rat, indicating good brain penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "A piperazine-fused heteroaromatic analogue showed a brain-to-plasma AUC ratio of 20.3 in rat, supporting efficient BBB crossing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Trazodone, a piperazine-aryl antidepressant, penetrated the BBB in mice with brain:plasma ratios consistent with efficacious dosing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "A piperazine-aryl butyl amide analogue was impermeable at baseline and was an ABC transporter substrate, with brain uptake increased by cyclosporin A, indicating efflux liability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C02"],
      "claim": "A piperazine-aryl fluoroethoxy amide tracer showed only low BBB penetration in rat PET, precluding CNS imaging.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C04"],
      "claim": "RGH-1756, a piperazine-aryl butoxy heteroaromatic, showed low whole-brain uptake (~1%) in monkey.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Pass: multiple close analogues with the same piperazine-aryl/butyl-dione scaffold demonstrate BBB penetration in PET and brain:plasma studies, and the query's ortho-fluorophenyl and xanthine-like core are consistent with CNS access. Negative analogues are less similar and contain amide/ether linkers or bulkier heteroaromatics, so their low-uptake/efflux phenotypes transfer less strongly.",
  "evidence_gaps": [
    "No direct experimental brain or plasma exposure data for the exact query molecule.",
    "Efflux liability of the query is inferred from analogues and physicochemical priors, not directly measured.",
    "Computed logD and pKa may differ from experimental values, affecting ionization and passive permeability estimates.",
    "Most supportive PET data are from baboon or mouse, not human; quantitative human CNS exposure is unknown."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

